        history = os.path.join(DATA, "reports", pid, "previous")
        os.makedirs(history, exist_ok=True)
        name = ("attempt-%d.json" % max(0, attempt - 1) if attempt > 0
                else "preexisting-%d.json" % int(time.time() * 1000))
